import{_ as o,l as i,o as e,c as s,v as t,p as n,x as r,d,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"BM25 与稀疏检索","description":"","frontmatter":{"title":"BM25 与稀疏检索","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/bm25-sparse.md","filePath":"llm/bm25-sparse.md","lastUpdated":1789023840000}'),h={name:"llm/bm25-sparse.md"};function c(_,a,E,A,B,u){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="bm25-与稀疏检索" tabindex="-1">BM25 与稀疏检索 <a class="header-anchor" href="#bm25-与稀疏检索" aria-label="Permalink to &quot;BM25 与稀疏检索&quot;">​</a></h1><div class="epigraph"><p>词法通道精确匹配高 IDF 的标识符。在订单号、报错码、函数名上，它经常是主通道，而不是「稠密之前的基线」。</p><footer>—— Robertson 等 BM25；倒排索引传统</footer></div><p><a href="/llm/multi-vector-late-interaction">上一课</a>用多向量补语义对齐。标识符仍常输给「语义流畅但不含该字符串」的段落。主干<a href="/llm/hybrid-retrieval">混合检索</a>已把 BM25 与稠密融合；本课在补层把稀疏检索本身写清，作为后课 SPLADE 的词法起点。缺口是：稀疏不是过时点缀。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BM25 把文档当词袋：词频饱和、IDF、长度归一。它对恰好出现的词极强，对同义与改写弱。稠密相反。真实查询常在一句自然语言里夹一个 <code>ECONNRESET</code>。只做向量，标识符被周围虚词带走；只做 BM25，换一种说法会零召回。本课钉稀疏这一侧的定义与实现陷阱，融合细节仍指向混合检索课。</p><p>分词必须与查询一致。中文分析器、代码 keyword 字段、是否 stemming，都是协议。换分析器等于换索引。</p><p><span class="marginnote">\\(k_1,b\\) 有默认值，字段加权（标题大于正文）通常比微调 \\(k_1\\) 更有效。先加权，再谈超参。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>倒排：词 → 文档列表 + 词频。查询时取各词 posting 求 BM25 分，可加字段权。过滤（租户、语言、版本）在倒排里做，与向量侧同一元数据，否则融合会抬出无权限文档。新文档先写倒排再写向量，稀疏可立即服务。</p><p>与切分的关系见 <a href="/llm/rag-chunking">RAG 切分</a>：块是倒排的文档单位，切太碎则 IDF 统计不稳，切太整则词袋平均掉小节。</p>',10)),(e(),n(m,null,{default:r(()=>[p(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOC%5B%22%E5%9D%97%E6%96%87%E6%9C%AC%22%5D%20--%3E%20ANA%5B%22%E5%88%86%E6%9E%90%E5%99%A8%22%5D%0A%20%20ANA%20--%3E%20INV%5B%22%E5%80%92%E6%8E%92%20posting%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20ANA2%5B%22%E5%90%8C%E4%B8%80%E5%88%86%E6%9E%90%E5%99%A8%22%5D%0A%20%20ANA2%20--%3E%20BM%5B%22BM25%22%5D%0A%20%20INV%20--%3E%20BM%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>IDF 把常见词压下去，罕见标识符权重大。饱和函数避免重复堆砌同一词无限加分。这是计数模型，没有同义。同义要靠查询扩展、同义词表，或后课学习到的稀疏表示（SPLADE）把隐含词写进扩展维度。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>BM25 不理解否定与语序。「不含超时」仍会命中含「超时」的段落。语义约束交给稠密或阅读器。下一课 SPLADE：用神经网络预测稀疏词权重，让词法通道也能「扩写」同义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BM25 是高 IDF 标识符的主通道；分析器属于协议。</li><li>权限过滤与切分单位必须与向量侧对齐。</li><li>词袋无同义、无语序；同义交给扩展或 SPLADE。</li><li>出处：Robertson BM25；混合检索课的融合。</li></ul>',6))])}const D=o(h,[["render",c]]);export{f as __pageData,D as default};
